#include <iostream>
#include <string>
#include <vector>

/**
 * Superclass Object
 */
class Object {
public:
    virtual ~Object() {}
};

/**
 * Motor component class - used for composition in Vehicle
 */
class Motor {
private:
    int horsepower;
public:
    Motor(int hp) : horsepower(hp) {}
    int getHorsepower() const { return horsepower; }
    void setHorsepower(int hp) { horsepower = hp; }
};

/**
 * Vehicle base class inheriting from Object
 */
class Vehicle : public Object {
protected:
    std::string brand;
    int year;
    float weight;
    Motor motor; // Composition
public:
    Vehicle(std::string b, int y, float w, int hp) : brand(b), year(y), weight(w), motor(hp) {}
    virtual ~Vehicle() {}

    // Perimeter methods
    std::string getBrand() const { return brand; }
    void setBrand(std::string b) { brand = b; }

    virtual void displayInfo() const = 0; // Polymorphism
};

class Car : public Vehicle {
private:
    int doors;
    std::string fuelType;
    bool isElectric;
public:
    Car(std::string b, int y, float w, int hp, int d, std::string f, bool e) 
        : Vehicle(b, y, w, hp), doors(d), fuelType(f), isElectric(e) {}

    // Perimeter methods
    int getDoors() const { return doors; }
    void setDoors(int d) { doors = d; }

    void displayInfo() const override {
        std::cout << "Car: " << brand << " (" << year << "), Doors: " << doors << std::endl;
    }
};

class Boat : public Vehicle {
private:
    float hullLength;
    bool hasCabin;
    std::string engineType;
public:
    Boat(std::string b, int y, float w, int hp, float hl, bool c, std::string e) 
        : Vehicle(b, y, w, hp), hullLength(hl), hasCabin(c), engineType(e) {}

    float getHullLength() const { return hullLength; }
    void setHullLength(float hl) { hullLength = hl; }

    void displayInfo() const override {
        std::cout << "Boat: " << brand << ", Length: " << hullLength << "ft" << std::endl;
    }
};

class Airplane : public Vehicle {
private:
    int altitudeLimit;
    int wingspan;
    bool isJet;
public:
    Airplane(std::string b, int y, float w, int hp, int al, int ws, bool ij) 
        : Vehicle(b, y, w, hp), altitudeLimit(al), wingspan(ws), isJet(ij) {}

    int getAltitudeLimit() const { return altitudeLimit; }
    void setAltitudeLimit(int al) { altitudeLimit = al; }

    void displayInfo() const override {
        std::cout << "Airplane: " << brand << ", Max Altitude: " << altitudeLimit << "ft" << std::endl;
    }
};

int main() {
    // Demonstration of polymorphism
    std::vector<Vehicle*> fleet;
    fleet.push_back(new Car("Toyota", 2022, 1500.0f, 200, 4, "Gas", false));
    fleet.push_back(new Boat("SeaRay", 2021, 3000.0f, 500, 25.5f, true, "Outboard"));
    fleet.push_back(new Airplane("Boeing", 2020, 50000.0f, 50000, 35000, 100, true));

    for (const auto v : fleet) {
        v->displayInfo();
    }

    // Cleanup
    for (auto v : fleet) delete v;

    return 0;
}
```

